function check(input, actual, expected) {
  const [s] = input;
  if (typeof actual !== 'string' || actual.length !== expected.length) return false;
  let depth = 0;
  for (const ch of actual) {
    if (ch === '(') depth++;
    else if (ch === ')' && --depth < 0) return false;
  }
  if (depth !== 0) return false;
  // actual must be s with some brackets deleted: match it as a subsequence that keeps every letter.
  let j = 0;
  for (let i = 0; i < s.length; i++) {
    if (j < actual.length && s[i] === actual[j]) j++;
    else if (s[i] !== '(' && s[i] !== ')') return false;
  }
  return j === actual.length;
}

