function minRemoveToMakeValid(s) {
  // Try every subset of brackets to keep and return a valid result that keeps the most of them.
  const brackets = [];
  for (let i = 0; i < s.length; i++) if (s[i] === '(' || s[i] === ')') brackets.push(i);
  let best = null;
  for (let mask = 0; mask < 2 ** brackets.length; mask++) {
    const drop = new Set(brackets.filter((_, b) => !(mask >> b & 1)));
    const kept = [...s].filter((_, i) => !drop.has(i)).join('');
    let depth = 0, ok = true;
    for (const ch of kept) {
      if (ch === '(') depth++;
      if (ch === ')') depth--;
      if (depth < 0) ok = false;
    }
    if (ok && depth === 0 && (best === null || kept.length > best.length)) best = kept;
  }
  return best;
}

