function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 12);
  // Some inputs lean towards '(' and others towards ')', so either kind may need removing.
  const open = 0.15 + rand() * 0.4, close = 0.15 + rand() * 0.4;
  let s = '';
  for (let i = 0; i < n; i++) {
    const r = rand();
    s += r < open ? '(' : r < open + close ? ')' : String.fromCharCode(97 + Math.floor(rand() * 26));
  }
  return [s];
}
